tool_input.command:
cat > /tmp/test-threshold.js << 'EOF'
import fs from 'fs';
import os from 'os';
import path from 'path';

// Import the functions we need
import { loadDataset, runEvaluations, generateReport, writeReport } from '/private/tmp/100-tricks-runs/d21/with/h2-eval-thresholds/r1/packages/frai-core/src/eval/index.js';

// Create a temporary directory
const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-test-'));

// Write test data
const outputsPath = path.join(tmpDir, 'outputs.json');
const referencesPath = path.join(tmpDir, 'references.json');

fs.writeFileSync(outputsPath, JSON.stringify(['hello', 'world', 'test'], null, 2));
fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world', 'other'], null, 2));

// Run evaluation
const dataset = loadDataset({ outputsPath, referencesPath });
const evaluations = runEvaluations({
  outputs: dataset.outputs,
  references: dataset.references
});

console.log('Evaluations:', JSON.stringify(evaluations, null, 2));

// Test 1: Report with passing threshold
const reportPass = generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds: { exact_match: 0.5 }
});

console.log('\n=== Test 1: Passing Threshold ===');
console.log('Passed:', reportPass.passed);
console.log('Thresholds:', JSON.stringify(reportPass.thresholds, null, 2));

// Test 2: Report with failing threshold
const reportFail = generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds: { exact_match: 0.9 }
});

console.log('\n=== Test 2: Failing Threshold ===');
console.log('Passed:', reportFail.passed);
console.log('Thresholds:', JSON.stringify(reportFail.thresholds, null, 2));

// Test 3: Report with no threshold (original behavior)
const reportNoThreshold = generateReport({
  evaluations,
  outputsPath,
  referencesPath
});

console.log('\n=== Test 3: No Thresholds ===');
console.log('Has passed field:', 'passed' in reportNoThreshold);
console.log('Has thresholds field:', 'thresholds' in reportNoThreshold);

// Test 4: Markdown format with thresholds
const reportMarkdown = generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds: { exact_match: 0.9, toxicity: 0.8 }
});

const reportPath = path.join(tmpDir, 'report.md');
writeReport({
  report: reportMarkdown,
  format: 'markdown',
  reportPath
});

const markdownContent = fs.readFileSync(reportPath, 'utf8');
console.log('\n=== Test 4: Markdown Output (excerpt) ===');
console.log(markdownContent.substring(0, 500));

// Clean up
fs.rmSync(tmpDir, { recursive: true, force: true });

console.log('\n✓ All tests completed successfully');
EOF

node /tmp/test-threshold.js
